func:
// 只处理“人已确认”的提议（附录 A.4 第 2 条）；写入 ERPNext 后把每张单据作为 erp.doc 发回总线，corr = 提议编号
const erp = global.get('wqErp');
const m = msg.payload;
if (!m || !m.data || m.mode !== erp.mode || m.data.status !== 'confirmed') return null;
node.status({ fill: 'blue', shape: 'dot', text: '执行 ' + m.data.proposal_id });
erp.execProposal(m).then((out) => {
  const bad = out.some((o) => o.payload.data.action === 'failed');
  node.status({ fill: bad ? 'red' : 'green', shape: 'dot', text: m.data.proposal_id + (bad ? ' 失败' : ' 已写入 ' + out.length + ' 张') });
  node.send([out]);
}).catch((e) => { node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 50) }); node.error(e.message, msg); });
return null;

// 设备事件 → ERPNext 作业卡：每完成一件记一条工时（按工厂时间）；一道工序做完就提交作业卡；
// 最后一道工序做完，按合格数做完工入库（扣原材料、加成品，工单完工数随之更新）
const erp = global.get('wqErp');
const m = msg.payload;
if (!m || !m.data || m.mode !== erp.mode || !m.data.work_order) return null;
let job = null;
if (m.data.event === 'cycle_end') job = erp.onCycleEnd(m);
else if (m.data.event === 'op_complete') job = erp.onOpComplete(m);
if (!job) return null;
job.then((out) => {
  if (out.length) node.status({ fill: 'green', shape: 'dot', text: m.data.work_order + ' ' + m.data.operation.split(' ')[0] + ' ' + m.data.event });
  node.send([out]);
}).catch((e) => {
  node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 50) });
  node.error(e.message, msg);
  // 写 ERPNext 失败也发到总线（erp.doc，action=failed），看板、AI 和老师都能看到原因
  node.send([[erp.failed('Job Card', e, { corr: m.corr, mode: m.mode, extra: { work_order: m.data.work_order, operation: m.data.operation, event: m.data.event } })]]);
});
return null;

// 三坐标测量值 → ERPNext 质量检验单：一件零件的全部特性到齐后建一张，关联到“零件检验”工序的作业卡
const erp = global.get('wqErp');
const m = msg.payload;
if (!m || !m.data || m.mode !== erp.mode) return null;
erp.onMeasurement(m).then((out) => {
  if (out.length) node.status({ fill: 'green', shape: 'dot', text: m.data.part_serial + ' 检验单已建' });
  node.send([out]);
}).catch((e) => {
  node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 50) });
  node.error(e.message, msg);
  // 写 ERPNext 失败也发到总线（erp.doc，action=failed），看板、AI 和老师都能看到原因
  node.send([[erp.failed('Quality Inspection', e, { corr: m.corr, mode: m.mode, extra: { work_order: m.data.work_order, part_serial: m.data.part_serial } })]]);
});
return null;

// 设计发布 → ERPNext；工艺规程生效 → 新版 BOM 工序（第 13 轮）。FreeCAD 发布 → ERPNext：物料版本号加一；BOM 用量变了就建新版 BOM；STEP、图纸、G 代码作为附件挂到物料上
const erp = global.get('wqErp');
const m = msg.payload;
if (!m || !m.data || m.mode !== erp.mode) return null;
if (!['design.release', 'design.gcode', 'process.release'].includes(m.type)) return null;   // 待审、退回等消息不写 ERPNext
const job = m.type === 'design.release' ? erp.onRelease(m) : m.type === 'process.release' ? erp.onProcess(m) : erp.onGcode(m);
job.then((out) => {
  node.status({ fill: 'green', shape: 'dot', text: m.data.item + (m.type === 'process.release' ? ' 工艺 rev ' : ' rev ') + m.data.revision });
  node.send([out]);
}).catch((e) => {
  node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 50) });
  node.error(e.message, msg);
  // 写 ERPNext 失败也发到总线（erp.doc，action=failed），看板、AI 和老师都能看到原因
  node.send([[erp.failed('Item', e, { corr: m.corr, mode: m.mode, extra: { name: m.data.item, revision: m.data.revision } })]]);
});
return null;

// 每 30 秒看一次 ERPNext 里有没有新改的订单、工单、请购单、采购单（例如学生直接在 ERPNext 里操作），有就发到总线
const erp = global.get('wqErp');
erp.poll().then((out) => {
  node.status({ fill: 'grey', shape: 'dot', text: new Date().toLocaleTimeString() + ' 变化 ' + out.length });
  node.send([out]);
}).catch((e) => { node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 50) }); node.error(e.message, msg); });
return null;

// 每 60 秒取一次库存（Bin），有变化的发到总线；看板的“关键物料”和算料都用它
const erp = global.get('wqErp');
erp.bins().then((out) => {
  node.status({ fill: 'grey', shape: 'dot', text: new Date().toLocaleTimeString() + ' 库存变化 ' + out.length });
  node.send([out]);
}).catch((e) => { node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 50) }); node.error(e.message, msg); });
return null;
